function validate([m, n]) {
  if (!Number.isInteger(m) || m < 1 || m > 9) return 'm is a whole number from 1 to 9.';
  if (!Number.isInteger(n) || n < 1 || n > 9) return 'n is a whole number from 1 to 9.';
  return null;
}

