function numberOfPatterns(m, n) {
  const skip = Array.from({ length: 10 }, () => new Array(10).fill(0));
  skip[1][3] = skip[3][1] = 2;
  skip[4][6] = skip[6][4] = 5;
  skip[7][9] = skip[9][7] = 8;
  skip[1][7] = skip[7][1] = 4;
  skip[2][8] = skip[8][2] = 5;
  skip[3][9] = skip[9][3] = 6;
  skip[1][9] = skip[9][1] = 5;
  skip[3][7] = skip[7][3] = 5;
  const visited = new Array(10).fill(false);

  function backtrack(key, length) {
    let total = length >= m ? 1 : 0;
    if (length === n) {
      return total;
    }
    visited[key] = true;
    for (let next = 1; next <= 9; next++) {
      const middle = skip[key][next];
      if (!visited[next] && (middle === 0 || visited[middle])) {
        total += backtrack(next, length + 1);
      }
    }
    visited[key] = false;
    return total;
  }

  return backtrack(1, 1) * 4 + backtrack(2, 1) * 4 + backtrack(5, 1);
}

