function numberOfPatterns(m, n) {
  // Extend every path from every key, checking strokes with grid geometry instead of a table.
  const row = key => Math.floor((key - 1) / 3);
  const col = key => (key - 1) % 3;
  const used = new Set();
  let count = 0;
  const extend = path => {
    if (path.length >= m && path.length <= n) count++;
    if (path.length >= n) return;
    const last = path[path.length - 1];
    for (let key = 1; key <= 9; key++) {
      if (used.has(key)) continue;
      const rowSum = row(last) + row(key);
      const colSum = col(last) + col(key);
      if (rowSum % 2 === 0 && colSum % 2 === 0 && !used.has((rowSum / 2) * 3 + colSum / 2 + 1)) continue;
      used.add(key);
      path.push(key);
      extend(path);
      path.pop();
      used.delete(key);
    }
  };
  for (let start = 1; start <= 9; start++) {
    used.add(start);
    extend([start]);
    used.delete(start);
  }
  return count;
}

