function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  if (size === 'large') return [1 + pick(9), 9];
  // Small cases keep n low so the brute force stays quick; m may exceed n.
  return [1 + pick(6), 1 + pick(5)];
}
